// PMS → CRS: "Read the message"                    (workflow: PMS send · email and WhatsApp)
// Mode: Run Once for All Items.
//
// The PMS decides WHAT and WHEN (D27-98) and sends named facts, never
// sentences (D17-87): the words the guest reads are written HERE, where they
// are changed without a release of the PMS. This workflow sends EVERY PMS
// guest message (D27-186): every email from the CRS's mailbox, and on WhatsApp
// the booking voucher, the check-in code, the tax invoice and the review
// request, all from the one Fidato number. Since D27-264 the voucher IS the
// confirmation and there is no reminder: booking_confirmation, stay_reminder
// and checkin_link are not used. D27-266: WhatsApp goes through the CRS's
// approved templates; a check-in link comes only where the hotel has online
// check-in on.
//
// ── THE OWNER'S SETTINGS: edit these, nothing below them ────────────────────
// The mailbox the guest sees the email from. Until it is filled in, every
// email is refused with a sentence the desk sees.
const FROM = "Fidato Hotels <crs@fidatohotels.com>";
const REPLY_TO = "crs@fidatohotels.com";
// WhatsApp: the PMS's kind of message → the Meta template, and the fields for
// its {{1}}, {{2}}, … in order (docs/go-live/whatsapp-templates.md). LANGUAGE
// is the language each template was approved in. A kind missing here is
// refused with a sentence the desk sees.
const LANGUAGE = "en";
const WHATSAPP = {
  // An Authentication template (Copy code): Meta writes its words.
  "guest-link-code": { name: "guest_page_code", code: "data.code" },
  "review": { name: "review_request", body: ["to.name", "hotel.name", "data.link"] },
};
// THE VOUCHER ON WHATSAPP (D27-235 2.2, D27-241): the CRS's ALREADY APPROVED
// voucher template - the PDF as its document, and eight NAMED fields. Type its
// exact name here, as WhatsApp Manager → Message templates shows it (the CRS's
// own workflow file ships it as "REPLACE_WITH_TEMPLATE_NAME"). Emptied, the
// WhatsApp voucher is refused with a sentence the desk sees; the voucher email
// still goes. D27-266: the CRS's reservation_confirmation, as run live.
const VOUCHER_TEMPLATE = "reservation_confirmation";
const VOUCHER_LANGUAGE = "en";
// The template's own field names, in its order, and the PMS fact for each.
const VOUCHER_FIELDS = [
  ["name_1", "data.guestName"], ["hotel_id", "data.reference"], ["hotel", "data.hotelName"],
  ["ck_in", "data.checkInLong"], ["ck_out", "data.checkOutLong"], ["rm_type", "data.roomTypes"],
  ["no_guest", "data.guests"], ["crs_nom", "data.officePhone"],
];
// THE TAX INVOICE ON WHATSAPP (D27-252, D27-261): the PMS's own new template,
// `tax_invoice` (docs/go-live/whatsapp-templates.md) - the invoice PDF as its
// document and five NAMED fields. Until Meta approves it, Meta refuses the
// message and the desk sees why; the email with the PDF still goes.
const INVOICE_TEMPLATE = "tax_invoice";
const INVOICE_FIELDS = [
  ["guest_name", "data.guestName"], ["hotel", "data.hotelName"], ["invoice_no", "data.invoiceNumber"],
  ["invoice_date", "data.invoiceDate"], ["amount", "data.total"],
];
// How long a sent message id is remembered, so a retry is not sent twice.
const KEEP_DAYS = 30;

// The words of each email. DRAFTS for the owner: change them here.
const EMAILS = {
  // The voucher email (D27-264): the voucher PDF attached. The check-in line
  // only when a link came - none while online check-in is off (D27-266).
  "booking-confirmation": (d, m) => ({
    subject: `Your booking at ${d.hotelName} is confirmed (${d.reference})`,
    lines: [
      `Hello ${d.guestName},`,
      `Your stay at ${d.hotelName} is confirmed.`,
      `Booking: ${d.reference}`,
      `Check-in: ${d.checkInText}`,
      `Check-out: ${d.checkOutText} (${d.nights} nights)`,
      m.file?.base64 ? "Your reservation voucher is attached." : null,
      d.link ? `To save time at the desk, you can fill in your check-in details here: ${d.link}` : null,
    ],
  }),
  // The check-in code by email (D27-207).
  "guest-link-code": (d) => ({
    subject: `Your check-in code for ${d.hotelName}`,
    lines: [
      `Hello ${d.guestName},`,
      `Your code is ${d.code}`,
      "It works for 10 minutes. Do not share it with anyone.",
      `Booking: ${d.reference}`,
    ],
  }),
  // The tax invoice, its PDF attached (D27-252).
  "invoice": (d) => ({
    subject: `Your tax invoice from ${d.hotelName} (${d.invoiceNumber})`,
    lines: [
      `Hello ${d.guestName},`,
      `Your tax invoice ${d.invoiceNumber}, dated ${d.invoiceDate}, for ${d.total} is attached.`,
      d.reference ? `Booking: ${d.reference}` : null,
      `Thank you for staying at ${d.hotelName}.`,
    ],
  }),
  // A report after the night audit, to one of the hotel's own people (D27-261).
  "report": (d, m) => ({
    subject: `${d.reportTitle} - ${d.hotelName} - ${d.businessDate}`,
    lines: [
      `Hello ${m.to?.name ?? ""},`,
      `The ${d.reportTitle} for ${d.hotelName}, business date ${d.businessDate}, is attached.`,
      "Sent after the night audit. The owner, an administrator or the GM changes who gets it in Settings, Messages.",
    ],
  }),
  "review": (d, m) => ({
    subject: `Thank you for staying at ${m.hotel?.name ?? ""}`,
    lines: [
      `Hello ${m.to?.name ?? ""},`,
      `Thank you for staying at ${m.hotel?.name ?? ""}.`,
      `If you have a minute, we would be grateful for a review: ${d.link}`,
    ],
  }),
  // Connection health (D27-276): a connection turned red. To the owner's
  // address in the PMS server's settings (HEALTH_ALERT_EMAIL), at most once an
  // hour per connection, and never while emails themselves are not working.
  "health-alert": (d) => ({
    subject: `Not working: ${d.connection}`,
    lines: [
      `${d.connection} has stopped working${d.hotelName ? ` at ${d.hotelName}` : ""}.`,
      d.problem,
      d.lastError ? `Last error: ${d.lastError}` : null,
      `Last success: ${d.lastSuccess || "none recorded"}`,
      `Noticed at ${d.at}. Settings, Modules and connections, Connection health shows every connection.`,
    ],
  }),
};
// ─────────────────────────────────────────────────────────────────────────────

const m = $input.first().json.body ?? {};
const stop = (statusCode, answer) => [{ json: { stop: true, statusCode, answer } }];

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(m.messageId ?? "")) {
  return stop(400, { ok: false, error: "No message id." });
}

// ALREADY SENT: the PMS timed out waiting for the answer and tried again.
const memory = $getWorkflowStaticData("global");
memory.sent = memory.sent ?? {};
const now = Date.now();
for (const [id, at] of Object.entries(memory.sent)) {
  if (now - at > KEEP_DAYS * 86400000) delete memory.sent[id];
}
if (memory.sent[m.messageId]) return stop(200, { ok: true, duplicate: true });

const d = m.data ?? {};
// The PDF, when the PMS sends one, as the attachment called "data".
const binary = m.file?.base64
  ? { data: { data: m.file.base64, mimeType: m.file.contentType || "application/pdf", fileName: m.file.name || "document.pdf" } }
  : undefined;

if (m.channel === "email") {
  if (!FROM) return stop(503, { ok: false, error: "The CRS workflow has no mailbox to send from yet." });
  const to = String(m.to?.email ?? "").trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) return stop(422, { ok: false, error: "No email address for the guest." });
  const words = EMAILS[m.kind];
  if (!words) return stop(422, { ok: false, error: `No email for "${m.kind}" in this workflow.` });
  const { subject, lines } = words(d, m);
  const kept = lines.filter(Boolean);
  // A guest's name is typed by people: it is text in the email, never HTML.
  /* THE CRS'S COLOURS (D27-172, V2): ink text, the orange rule, grey small
     print - a short letter; the voucher's full design is the attached PDF.
     A link is made clickable AFTER the line is escaped, so nothing typed
     can become markup. */
  const letter = (lines, hotel) => [
    '<div style="font-family:Arial,Helvetica,sans-serif;color:#142B3A;max-width:560px;margin:0 auto">',
    '<div style="height:4px;background:#FE611F"></div>',
    ...lines.map((l) => `<p style="font-size:15px;line-height:1.5;margin:16px 0">${
      esc(l).replace(/https?:\/\/[^\s<"']+/g, (u) => `<a href="${u}" style="color:#FE611F">${u}</a>`)}</p>`),
    `<p style="font-size:12px;color:#67737E;border-top:1px solid #DFE3E6;padding-top:12px">${esc(hotel)}</p>`,
    "</div>",
  ].join("\n");
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  return [{
    json: {
      stop: false, email: true, messageId: m.messageId,
      from: FROM, replyTo: REPLY_TO || FROM, to, subject,
      text: kept.join("\n\n"),
      html: letter(kept, m.hotel?.name ?? ""),
      attachments: binary ? "data" : "",
    },
    ...(binary ? { binary } : {}),
  }];
}

// WhatsApp: every kind in WHATSAPP above (D27-186), and the voucher below.
const t = WHATSAPP[m.kind];
if (!t && m.kind !== "booking-voucher" && m.kind !== "invoice") {
  return stop(422, { ok: false, error: `No WhatsApp template for "${m.kind}" in this workflow.` });
}
let digits = String(m.to?.phone ?? "").replace(/\D/g, "");
if (digits.length === 10) digits = `91${digits}`;
if (digits.length < 11) return stop(422, { ok: false, error: "No WhatsApp number for the guest." });
const numberId = String(m.from?.phoneNumberId ?? "").replace(/\D/g, "");
if (!numberId) return stop(422, { ok: false, error: "The PMS sent no WhatsApp number id." });

// Meta refuses an EMPTY parameter, and a newline, a tab or four spaces inside one.
const flat = (v) => String(v ?? "").replace(/[\n\t\r]+/g, " ").replace(/ {4,}/g, "   ").trim() || "-";
const pick = (path) => path.split(".").reduce((o, k) => (o == null ? o : o[k]), m);

// THE VOUCHER: the PDF goes to Meta first ("Upload PDF to Meta"), and "Build
// the voucher message" sends the template with the id Meta answers.
const DOCUMENT = {
  "booking-voucher": { name: VOUCHER_TEMPLATE, language: VOUCHER_LANGUAGE, fields: VOUCHER_FIELDS, what: "voucher" },
  "invoice": { name: INVOICE_TEMPLATE, language: LANGUAGE, fields: INVOICE_FIELDS, what: "invoice" },
}[m.kind];
if (DOCUMENT) {
  if (!DOCUMENT.name) {
    return stop(503, { ok: false, error: `The ${DOCUMENT.what} template's name is not filled in in the CRS's sending workflow yet.` });
  }
  if (!binary) return stop(422, { ok: false, error: `No ${DOCUMENT.what} PDF came with the message.` });
  return [{
    json: {
      stop: false, email: false, upload: true, messageId: m.messageId,
      mediaUrl: `https://graph.facebook.com/v23.0/${numberId}/media`,
      graphUrl: `https://graph.facebook.com/v23.0/${numberId}/messages`,
      to: digits, filename: binary.data.fileName,
      template: {
        name: DOCUMENT.name, language: { code: DOCUMENT.language },
        body: DOCUMENT.fields.map(([name, path]) => ({ type: "text", parameter_name: name, text: flat(pick(path)) })),
      },
    },
    binary,
  }];
}
const components = t.code
  // An Authentication template: the code in the body and in its copy button.
  ? [
      { type: "body", parameters: [{ type: "text", text: flat(pick(t.code)) }] },
      { type: "button", sub_type: "url", index: "0", parameters: [{ type: "text", text: flat(pick(t.code)) }] },
    ]
  : [{ type: "body", parameters: t.body.map((p) => ({ type: "text", text: flat(pick(p)) })) }];
return [{
  json: {
    stop: false, email: false, messageId: m.messageId,
    graphUrl: `https://graph.facebook.com/v23.0/${numberId}/messages`,
    graphBody: {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: digits,
      type: "template",
      template: { name: t.name, language: { code: LANGUAGE }, components },
    },
  },
}];

// PMS → n8n: "Remember it"                                (both PMS send workflows)
// Mode: Run Once for All Items.
//
// Input: the send (HTTP Request with Never Error on, or the email node's
// success / error output). Sent: its id is remembered, so the PMS's retry of
// the SAME message is answered "already sent" and not sent again. Not sent:
// nothing is remembered - the PMS's next try must really try.

function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return { raw: body }; }
}

const msg = $("Read the message").first().json;
const res = $input.first().json;
const sent = res.statusCode !== undefined
  ? res.statusCode >= 200 && res.statusCode < 300
  : !res.error;

if (!sent) {
  const said = res.statusCode !== undefined
    ? `WhatsApp refused it (HTTP ${res.statusCode}): ${parse(res.body).error?.message ?? ""}`
    : `The email did not go: ${res.error?.message ?? res.error ?? ""}`;
  return [{ json: { statusCode: 502, answer: { ok: false, error: said.slice(0, 300).trim() } } }];
}

$getWorkflowStaticData("global").sent ??= {};
$getWorkflowStaticData("global").sent[msg.messageId] = Date.now();
return [{ json: { statusCode: 200, answer: { ok: true, ...(msg.markProblem ? { note: msg.markProblem } : {}) } } }];

// PMS → CRS: "Build the voucher message"               (workflow: PMS send · email and WhatsApp)
// Mode: Run Once for All Items. D27-235 2.2, D27-241.
//
// Input: "Upload PDF to Meta" (Full Response on, Never Error on). Meta answers
// the uploaded PDF's media id; this sends the CRS's voucher template with that
// document as its header and the eight named fields "Read the message" made.
// Refused: the PMS is answered at once and nothing is sent.

const msg = $("Read the message").first().json;
const res = $input.first().json;
const body = typeof res.body === "string" ? (() => { try { return JSON.parse(res.body); } catch { return {}; } })() : (res.body ?? {});
const ok = res.statusCode >= 200 && res.statusCode < 300 && body.id;
if (!ok) {
  const said = `Meta did not take the voucher PDF (HTTP ${res.statusCode ?? "-"}): ${body.error?.message ?? ""}`;
  return [{ json: { stop: true, statusCode: 502, answer: { ok: false, error: said.slice(0, 300).trim() } } }];
}
return [{
  json: {
    stop: false, messageId: msg.messageId,
    graphUrl: msg.graphUrl,
    graphBody: {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: msg.to,
      type: "template",
      template: {
        name: msg.template.name,
        language: msg.template.language,
        components: [
          { type: "header", parameters: [{ type: "document", document: { id: body.id, filename: msg.filename } }] },
          { type: "body", parameters: msg.template.body },
        ],
      },
    },
  },
}];
